INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'volunteer', 'n./v.', '/ˌvɒlənˈtɪə(r)/', '志愿者;志愿做;自愿', 'She decided to volunteer at the local animal shelter.', '她决定去当地的动物收容所做志愿者。', 'Volunteering', 1, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a volunteer guide', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'donate', 'v.', '/dəʊˈneɪt/', '捐赠;赠送', 'Many people donate food and clothes to the homeless shelter.', '许多人向无家可归者收容所捐赠食物和衣物。', 'Volunteering', 2, 0, 'senior', 'wordlist', 'elective1', 'U2', 'donate money', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'organisation', 'n.', '/ˌɔːɡənaɪˈzeɪʃn/', '组织;团体;机构', 'He works for a wildlife conservation organisation.', '他在一家野生动物保护组织工作。', 'Volunteering', 3, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a charity organisation', '美式拼 organization;美音 /ˌɔːrɡənəˈzeɪʃn/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'shelter', 'n./v.', '/ˈʃeltə(r)/', '收容所;庇护所;遮蔽;保护', 'Volunteers feed the dogs at the animal shelter every weekend.', '志愿者每个周末都到动物收容所给狗喂食。', 'Volunteering', 4, 0, 'senior', 'wordlist', 'elective1', 'U2', 'an animal shelter', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'campaign', 'n./v.', '/kæmˈpeɪn/', '运动;活动;参加(或发起)运动', 'Jackson led a campaign to reduce plastic pollution in his town.', '杰克逊在他的镇上发起了一场减少塑料污染的运动。', 'Volunteering', 5, 0, 'senior', 'wordlist', 'elective1', 'U2', 'lead a campaign', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'promote', 'v.', '/prəˈməʊt/', '促进;推动;宣传;推广', 'The club aims to promote the use of reusable water bottles.', '这个俱乐部旨在推广可重复使用水瓶的使用。', 'Volunteering', 6, 0, 'senior', 'wordlist', 'elective1', 'U2', 'promote the usage of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'urge', 'v./n.', '/ɜːdʒ/', '敦促;力劝;强烈的欲望', 'Volunteers urged local restaurants to stop using plastic straws.', '志愿者力劝当地餐馆停止使用塑料吸管。', 'Volunteering', 7, 0, 'senior', 'wordlist', 'elective1', 'U2', 'urge sb to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'movement', 'n.', '/ˈmuːvmənt/', '运动;movement(社会运动);移动', 'Thousands of young people have joined the green movement.', '成千上万的年轻人加入了环保运动。', 'Volunteering', 8, 0, 'senior', 'wordlist', 'elective1', 'U2', 'join a movement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'march', 'n./v.', '/mɑːtʃ/', '示威游行;行进', 'The students organised a march to raise awareness of water rights.', '学生们组织了一场游行来提高人们对水权的认识。', 'Volunteering', 9, 0, 'senior', 'wordlist', 'elective1', 'U2', 'organise a march', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'launch', 'v./n.', '/lɔːntʃ/', '启动;发起;推出;发射', 'The two boys launched a website to connect children with volunteer work.', '这两个男孩创建了一个网站,把孩子们和志愿工作联系起来。', 'Volunteering', 10, 0, 'senior', 'wordlist', 'elective1', 'U2', 'launch a database', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'database', 'n.', '/ˈdeɪtəbeɪs/', '数据库;资料库', 'They built a database of local volunteer opportunities.', '他们建立了一个当地志愿机会的数据库。', 'Volunteering', 11, 0, 'senior', 'wordlist', 'elective1', 'U2', 'build a database', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'urban', 'adj.', '/ˈɜːbən/', '城市的;都市的;城镇的', 'She volunteers with an urban farming group in the city.', '她在城里的一个城市农业团体做志愿者。', 'Volunteering', 12, 0, 'senior', 'wordlist', 'elective1', 'U2', 'urban farming', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'request', 'v./n.', '/rɪˈkwest/', '请求;要求', 'Many organisations request to be listed on the volunteer website.', '许多组织请求被列入这个志愿者网站。', 'Volunteering', 13, 0, 'senior', 'wordlist', 'elective1', 'U2', 'request to join', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'earn', 'v.', '/ɜːn/', '挣得;赢得;赚(钱)', 'The children earned money for charity by selling lemonade.', '孩子们靠卖柠檬水为慈善事业筹钱。', 'Volunteering', 14, 0, 'senior', 'wordlist', 'elective1', 'U2', 'earn money', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'purchase', 'v./n.', '/ˈpɜːtʃəs/', '购买;采购', 'He raised money to purchase GPS collars for the animals.', '他筹款为这些动物购买GPS颈圈。', 'Volunteering', 15, 0, 'senior', 'wordlist', 'elective1', 'U2', 'purchase GPS collars', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gallery', 'n.', '/ˈɡæləri/', '陈列室;展览馆;画廊', 'Xiao Meng works as a guide in the clock gallery of the museum.', '小萌在博物馆的钟表陈列室当导览员。', 'Volunteering', 16, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the clock gallery', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'emperor', 'n.', '/ˈempərə(r)/', '皇帝', 'Twenty-five emperors once lived in this ancient palace.', '曾有二十五位皇帝住在这座古老的宫殿里。', 'Volunteering', 17, 0, 'senior', 'wordlist', 'elective1', 'U2', 'an emperor''s palace', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'brick', 'n.', '/brɪk/', '砖;砖块', 'As the guide says, every brick of the palace has a story to tell.', '正如导览员所说,宫殿的每一块砖都有故事可讲。', 'Volunteering', 18, 0, 'senior', 'wordlist', 'elective1', 'U2', 'every brick', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'twin', 'n./adj.', '/twɪn/', '双胞胎之一;成对的', 'The twin brothers started the website together when they were fourteen.', '这对双胞胎兄弟十四岁时一起创办了这个网站。', 'Volunteering', 19, 0, 'senior', 'wordlist', 'elective1', 'U2', 'twin brothers', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mission', 'n.', '/ˈmɪʃn/', '使命;任务;使团', 'Their mission at the orphanage was to build a library.', '他们在孤儿院的任务是建一座图书馆。', 'Volunteering', 20, 0, 'senior', 'wordlist', 'elective1', 'U2', 'our mission', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'deliver', 'v.', '/dɪˈlɪvə(r)/', '履行(诺言);兑现;递送;发表', 'The students found that they could not deliver on this mission.', '学生们发现他们无法完成这项任务。', 'Volunteering', 21, 0, 'senior', 'wordlist', 'elective1', 'U2', 'deliver on a mission', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'construction', 'n.', '/kənˈstrʌkʃn/', '建筑;建造;施工', 'They were very bad at the most basic construction work.', '他们连最基本的建筑活儿都干得很糟。', 'Volunteering', 22, 0, 'senior', 'wordlist', 'elective1', 'U2', 'construction work', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'structure', 'n./v.', '/ˈstrʌktʃə(r)/', '结构;建筑物;构造;组织', 'Local men came back at night to rebuild the structure.', '当地人晚上回来重建那座建筑。', 'Volunteering', 23, 0, 'senior', 'wordlist', 'elective1', 'U2', 'rebuild the structure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'hire', 'v.', '/ˈhaɪə(r)/', '雇用;聘用;临时租用', 'It would have been better to hire local workers to do the job.', '雇当地工人来做这活儿本会更好。', 'Volunteering', 24, 0, 'senior', 'wordlist', 'elective1', 'U2', 'hire locals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'failure', 'n.', '/ˈfeɪljə(r)/', '失败;失败的人(或事)', 'Her failure at the simple act of gift giving taught her a lesson.', '她在送礼这件简单事上的失败给她上了一课。', 'Volunteering', 25, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a failure at', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'awkward', 'adj.', '/ˈɔːkwəd/', '令人尴尬的;难堪的;笨拙的', 'The most awkward part was her mistake over the gifts.', '最尴尬的部分是她在礼物上犯的错误。', 'Volunteering', 26, 0, 'senior', 'wordlist', 'elective1', 'U2', 'an awkward moment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'logical', 'adj.', '/ˈlɒdʒɪkl/', '合乎情理的;合逻辑的;必然的', 'Collecting hair bands for the girls seemed logical to her at first.', '起初为那些女孩收集发带在她看来合情合理。', 'Volunteering', 27, 0, 'senior', 'wordlist', 'elective1', 'U2', 'seem logical', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fashionable', 'adj.', '/ˈfæʃnəbl/', '流行的;时髦的;时兴的', 'She thought the gifts were cute and fashionable.', '她觉得这些礼物既可爱又时髦。', 'Volunteering', 28, 0, 'senior', 'wordlist', 'elective1', 'U2', 'cute and fashionable', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'uniform', 'n.', '/ˈjuːnɪfɔːm/', '制服;校服', 'The girls were wearing their crisp school uniforms.', '女孩们穿着干净挺括的校服。', 'Volunteering', 29, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a school uniform', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'regular', 'adj.', '/ˈreɡjələ(r)/', '通常的;平常的;有规律的;经常的', 'A short haircut is a regular part of the schoolgirl uniform there.', '短发是那里女生校服的一个常规部分。', 'Volunteering', 30, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a regular part', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'official', 'n./adj.', '/əˈfɪʃl/', '官员;要员;公务的;官方的', 'The girls'' hair is highly regulated by school officials.', '女孩们的头发受到学校官员的严格管理。', 'Volunteering', 31, 0, 'senior', 'wordlist', 'elective1', 'U2', 'school officials', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'resource', 'n.', '/rɪˈsɔːs/', '资源;财力;资料', 'With all my resources, I should have done more research first.', '拥有这么多资源,我本应先做更多调查。', 'Volunteering', 32, 0, 'senior', 'wordlist', 'elective1', 'U2', 'with all my resources', '美音 /ˈriːsɔːrs/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'criticize', 'v.', '/ˈkrɪtɪsaɪz/', '批评;批判;指责;挑剔', 'This kind of volunteering trip has been criticized recently.', '这类志愿旅行最近受到了不少批评。', 'Volunteering', 33, 0, 'senior', 'wordlist', 'elective1', 'U2', 'be criticized', '英式亦拼 criticise', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'intention', 'n.', '/ɪnˈtenʃn/', '打算;意图;目的', 'If you travel with the intention of helping, do your research first.', '如果你带着帮助他人的意图去旅行,先做好调查。', 'Volunteering', 34, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the intention of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'assume', 'v.', '/əˈsjuːm/', '假定;假设;认为', 'Don''t assume that others value the same things you do.', '别想当然地以为别人看重的东西和你一样。', 'Volunteering', 35, 0, 'senior', 'wordlist', 'elective1', 'U2', 'assume that', '美音 /əˈsuːm/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'educated', 'adj.', '/ˈedʒukeɪtɪd/', '受过教育的;有教养的', 'Even highly educated students may fail at simple practical tasks.', '即使是受过良好教育的学生也可能在简单的实际任务上失败。', 'Volunteering', 36, 0, 'senior', 'wordlist', 'elective1', 'U2', 'highly educated', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wage', 'n.', '/weɪdʒ/', '工资;报酬(通常按周计)', 'The advertisement offered only a small wage for hard work.', '这则广告对辛苦的工作只给很少的工资。', 'Volunteering', 37, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a small wage', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advertisement', 'n.', '/ədˈvɜːtɪsmənt/', '广告;启事', 'They designed an advertisement to find volunteers for the project.', '他们设计了一则广告来为项目招募志愿者。', 'Volunteering', 38, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a volunteer advertisement', '美音 /ˌædvərˈtaɪzmənt/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'band', 'n.', '/bænd/', '带;箍;乐队;一群', 'She had worn a hair band on her wrist for years.', '她手腕上戴发带已经很多年了。', 'Volunteering', 39, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a hair band', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'collar', 'n.', '/ˈkɒlə(r)/', '(动物的)颈圈;衣领', 'The money was used to buy GPS collars to protect the cheetahs.', '这笔钱被用来购买GPS颈圈以保护猎豹。', 'Volunteering', 40, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a GPS collar', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'soccer', 'n.', '/ˈsɒkə(r)/', '足球(运动)', 'The volunteers also played a few soccer games with the children.', '志愿者还和孩子们踢了几场足球。', 'Volunteering', 41, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a soccer game', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'county', 'n.', '/ˈkaʊnti/', '郡;(美国的)县', 'He organised a march in his county to protect water rights.', '他在自己所在的县组织了一场保护水权的游行。', 'Volunteering', 42, 0, 'senior', 'wordlist', 'elective1', 'U2', 'in the county', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'plastic', 'n./adj.', '/ˈplæstɪk/', '塑料;塑料的', 'He is determined to fight plastic pollution in his town.', '他决心在自己的镇上对抗塑料污染。', 'Volunteering', 43, 0, 'senior', 'wordlist', 'elective1', 'U2', 'plastic pollution', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'crop', 'v./n.', '/krɒp/', '剪短;庄稼;作物', 'The schoolgirls all had closely cropped hair.', '女生们的头发都剪得很短。', 'Volunteering', 44, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a cropped head', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u2.01', '①that 引导陈述宾语从句(think/know/believe/hope (that) ...)', 'A2', 11, '上外版选择性必修第一册 U2 — think/know/believe/hope/say/find 等动词后接陈述内容时,用连接词 that 引导宾语从句(口语中常省略),从句用陈述语序;不可用 if/what/whether 等引导一个完整的陈述。', 1, 'elective1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u2.02', '②if / whether 引导一般疑问的转述(ask/wonder/want to know ...)', 'A2', 11, '上外版选择性必修第一册 U2 — 把一个一般疑问句(Yes/No 问题)变成宾语从句时,用 if 或 whether 引导,从句改为陈述语序(主语在前、谓语在后);ask/wonder/want to know 等后接是否类内容时不用 that/what。', 2, 'elective1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u2.03', '③连接代词/副词引导特殊疑问宾语从句(陈述语序 + 时态呼应)', 'A2', 11, '上外版选择性必修第一册 U2 — 把特殊疑问句变成宾语从句时,保留疑问词 what/who/whom/where/when/why/how,从句改为陈述语序;主句为过去时,从句一般也用相应的过去时。', 3, 'elective1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Max believes ____ volunteering can change a young person''s whole life.', 'that', 'if', 'what', 'whether', 'A', 'believe 后接一个完整的陈述内容(志愿服务能改变人生),用 that 引导陈述宾语从句。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'I really hope ____ more students will join our recycling campaign this year.', 'if', 'that', 'whether', 'what', 'B', 'hope 后是对未来的陈述,用 that(可省略);不能用表示是否的 if/whether。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'The twins know ____ their website helps children find volunteer work.', 'whether', 'what', 'that', 'if', 'C', 'know 后是一句陈述(网站帮孩子找志愿工作),用 that 引导。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Jackson says ____ reusable bottles can cut down a lot of plastic waste.', 'if', 'what', 'whether', 'that', 'D', 'say 后接陈述内容,用 that 引导陈述宾语从句。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Many people think ____ young volunteers can truly make a difference.', 'that', 'whether', 'what', 'if', 'A', 'think 后是陈述(年轻志愿者能带来改变),用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Xiao Meng found ____ every brick in the palace seemed to tell a story.', 'if', 'that', 'what', 'whether', 'B', 'find 后接陈述发现,用 that 引导;不能用 if/whether。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'We all agreed ____ the animal shelter needed more weekend helpers.', 'what', 'whether', 'that', 'if', 'C', 'agree 后接一致意见的陈述,用 that 引导。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'The teacher explained ____ volunteering teaches us to value what we have.', 'if', 'what', 'whether', 'that', 'D', 'explain 后接陈述内容,用 that 引导陈述宾语从句。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Joris believes ____ even a child can help protect endangered animals.', 'that', 'if', 'whether', 'what', 'A', 'believe 后是陈述(孩子也能帮助保护动物),用 that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'She realised ____ doing research first would have saved a lot of trouble.', 'whether', 'that', 'what', 'if', 'B', 'realise 后接陈述领悟,用 that 引导;非是否问题。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'I promise ____ I will spend every Saturday morning at the shelter.', 'if', 'what', 'that', 'whether', 'C', 'promise 后接承诺的陈述,用 that 引导陈述宾语从句。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Pippa admitted ____ the group had failed at the only task they were given.', 'if', 'what', 'whether', 'that', 'D', 'admit 后接陈述承认,用 that 引导;不能用 if/whether。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Everyone hopes ____ the new campaign will reach the whole town soon.', 'that', 'if', 'what', 'whether', 'A', 'hope 后接对未来的陈述,用 that 引导。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'The volunteers learned ____ small daily efforts can add up to real change.', 'if', 'that', 'whether', 'what', 'B', 'learn 后接陈述所得,用 that 引导陈述宾语从句。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'He noticed ____ the local men quietly rebuilt the library every night.', 'what', 'if', 'that', 'whether', 'C', 'notice 后接陈述发现,用 that 引导;非是否或疑问内容。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'The article points out ____ good intentions alone are not always enough.', 'if', 'what', 'whether', 'that', 'D', 'point out 后接陈述观点,用 that 引导陈述宾语从句。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'I feel ____ helping others also makes the helper happier in the end.', 'that', 'if', 'whether', 'what', 'A', 'feel 后接陈述感受(可省 that),用 that 引导;不能用 if/whether/what。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'The guide added ____ twenty-five emperors had once lived in the palace.', 'whether', 'that', 'if', 'what', 'B', 'add 后接补充的陈述,用 that 引导陈述宾语从句。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Our team is sure ____ reusable bottles will become popular before long.', 'if', 'what', 'that', 'whether', 'C', 'be sure 后接陈述把握,用 that 引导;非是否问题。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.01'), 'Volunteers often say ____ giving their time is far more rewarding than money.', 'if', 'what', 'whether', 'that', 'D', 'say 后接陈述内容,用 that 引导陈述宾语从句。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'The interviewer asked Xu Yuan ____ she had any volunteer experience before.', 'if', 'that', 'what', 'which', 'A', 'ask 后转述一个一般疑问(有没有经验),用 if 引导,从句陈述语序;不能用 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'I wonder ____ the animal shelter still needs helpers this weekend.', 'what', 'whether', 'that', 'who', 'B', 'wonder 后转述是否类问题,用 whether(= if)引导,从句陈述语序。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'She wanted to know ____ her attendance at the expo would be recorded.', 'that', 'what', 'if', 'when', 'C', 'want to know 后转述 Yes/No 问题(会不会被记录),用 if 引导。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'Jackson asked the restaurant owners ____ they would sell paper bottles.', 'what', 'that', 'which', 'whether', 'D', 'ask 后转述一般疑问(愿不愿意卖),用 whether 引导,陈述语序。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'The boys did not know ____ the website would attract any visitors at all.', 'whether', 'that', 'what', 'who', 'A', 'know(否定)后转述是否问题,选项中只有 whether 成立(that/what/who 均不引导是否类转述)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'Please tell me ____ the charity accepts second-hand clothes as donations.', 'that', 'if', 'what', 'which', 'B', 'tell 后转述 Yes/No 问题(收不收旧衣),用 if 引导。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'Jiang was not sure ____ all the food at the expo could be traced to its source.', 'what', 'who', 'whether', 'that', 'C', 'be sure(否定)后转述是否问题,用 whether 引导,陈述语序。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'He wondered ____ his small donation could really help the shelter at all.', 'what', 'that', 'which', 'if', 'D', 'wonder 后转述是否问题(能不能帮上),用 if 引导。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'The students asked ____ the orphanage really needed a new library.', 'whether', 'what', 'that', 'who', 'A', 'ask 后转述 Yes/No 问题(是否真的需要),用 whether 引导。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'I''d like to find out ____ the march has been approved by the county yet.', 'what', 'if', 'that', 'which', 'B', 'find out 后转述是否问题(有没有获批),用 if 引导。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'She asked the guide ____ ordinary visitors could join the tour for free.', 'that', 'what', 'whether', 'who', 'C', 'ask 后转述一般疑问(能否免费参加),用 whether 引导,陈述语序。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'We are not certain ____ the campaign has changed people''s daily habits.', 'what', 'who', 'that', 'whether', 'D', 'be certain(否定)后转述是否问题,用 whether 引导。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'He asked the officials ____ a short haircut was required for every girl.', 'if', 'that', 'what', 'which', 'A', 'ask 后转述 Yes/No 问题(是否要求短发),用 if 引导,陈述语序。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'I wonder ____ the two boys planned the whole project on their own.', 'what', 'whether', 'that', 'who', 'B', 'wonder 后转述是否问题(是否独立完成),用 whether 引导。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'Could you tell me ____ the volunteer fair will be held this December?', 'that', 'what', 'if', 'which', 'C', 'tell 后转述 Yes/No 问题(是否举办),用 if 引导,陈述语序。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'The teacher asked us ____ we had ever donated to a charity before.', 'what', 'who', 'which', 'whether', 'D', 'ask 后转述是否问题(有没有捐过),用 whether 引导。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'Pippa wondered ____ her gifts would really be useful to the local girls.', 'if', 'that', 'what', 'which', 'A', 'wonder 后转述是否问题(礼物是否有用),用 if 引导,陈述语序。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'Nobody knew ____ the local men would come back to fix the wall at night.', 'what', 'whether', 'that', 'who', 'B', 'know(否定)后转述是否问题,用 whether 引导,陈述语序。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'She asked the leader ____ new volunteers needed any special training first.', 'that', 'what', 'if', 'which', 'C', 'ask 后转述 Yes/No 问题(是否需要培训),用 if 引导。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.02'), 'I''m wondering ____ our paper bottles can really replace plastic ones.', 'what', 'who', 'that', 'whether', 'D', 'wonder 后转述是否问题(能否替代),用 whether 引导,陈述语序。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'At the interview she asked me ____ my greatest strength was.', 'what', 'if', 'that', 'whether', 'A', '转述特殊疑问 ''What is your greatest strength?'',保留 what,从句用陈述语序 what my strength was。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'The leader explained ____ we should report to after the interview.', 'that', 'whom', 'if', 'what', 'B', '转述 ''Whom should you report to?'',保留 whom,从句陈述语序。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'Jiang was told ____ she would work during the import expo.', 'if', 'that', 'where', 'whether', 'C', '转述 ''Where will you work?'',保留 where,从句陈述语序 where she would work。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'I''d like to know ____ first started this volunteer website.', 'that', 'if', 'whether', 'who', 'D', '转述 ''Who started the website?'',who 作从句主语,语序不变。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'The interviewer wondered ____ I had organised so many activities.', 'how', 'if', 'that', 'whether', 'A', '转述 ''How did you organise them?'',保留 how,从句陈述语序。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'She wanted to know ____ I would like to serve as a volunteer.', 'that', 'when', 'if', 'whether', 'B', '转述 ''When would you like to serve?'',保留 when,从句陈述语序。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'Nobody could tell us ____ the old guide had remembered every clock.', 'if', 'that', 'how', 'whether', 'C', '转述 ''How did she remember them?'',保留 how,主句过去时从句也用过去完成。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'The teacher asked us ____ we wanted to help in our community.', 'that', 'if', 'whether', 'why', 'D', '转述 ''Why do you want to help?'',保留 why,从句陈述语序。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'I forget ____ the volunteer fair will be held this year.', 'where', 'if', 'that', 'whether', 'A', '转述 ''Where will it be held?'',保留 where,从句陈述语序。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'He explained ____ his work experience related to the volunteer position.', 'that', 'how', 'if', 'whether', 'B', '转述 ''How does your experience relate?'',保留 how,主句过去时从句用过去时 related。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'She finally understood ____ her mother had encouraged her to volunteer.', 'if', 'that', 'why', 'whether', 'C', '转述 ''Why did her mother encourage her?'',保留 why,主句过去时从句用过去完成。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'Please tell me ____ I can sign up for the weekend shelter work.', 'that', 'if', 'whether', 'how', 'D', '转述 ''How can I sign up?'',保留 how,从句陈述语序。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'The girls did not understand ____ the strange hair bands were for.', 'what', 'if', 'that', 'whether', 'A', '转述 ''What are the bands for?'',保留 what(介词 for 留在句末),从句陈述语序。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'I asked the guide ____ many visitors came to the palace each day.', 'that', 'how', 'if', 'whether', 'B', '转述 ''How many visitors come each day?'',保留 how many,从句陈述语序。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'We were curious about ____ the twins had got their first idea.', 'if', 'that', 'where', 'whether', 'C', '转述 ''Where did they get the idea?'',保留 where,主句过去时从句用过去完成。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'Can you tell me ____ is in charge of the recycling campaign?', 'if', 'that', 'whether', 'who', 'D', '转述 ''Who is in charge?'',who 作从句主语,语序不变。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'The officials decided ____ the schoolgirls should wear their hair.', 'how', 'if', 'that', 'whether', 'A', '转述 ''How should the girls wear their hair?'',保留 how,从句陈述语序。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'She showed the new helper ____ she could keep the food safe.', 'that', 'how', 'if', 'whether', 'B', '转述 ''How can I keep the food safe?'',保留 how,主句过去时从句用过去时 could。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'Then I was supposed to tell her ____ I expected from the position.', 'if', 'that', 'what', 'whether', 'C', '转述 ''What do you expect from the position?'',保留 what 作宾语,从句陈述语序。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U2' AND code='se1u2.03'), 'I really want to find out ____ this strength will help me as a volunteer.', 'if', 'that', 'whether', 'how', 'D', '转述 ''How will this strength help you?'',保留 how,从句陈述语序。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Boy Who Helps Cheetahs', 'Joris is only ten years old, but he has already done something many adults never do. Living in Seattle, he became aware that cheetahs were under the threat of extinction. Instead of just feeling sad, he decided to act. He sold lemonade, flowers and T-shirts, and organised skating parties and a garage sale to earn money. In this way he raised more than fourteen thousand dollars. With that money, he helped to purchase GPS collars that can track and protect the animals in the wild. Joris has also volunteered to help in a wildlife conservation organisation. When people ask him why a child should worry about animals so far away, he simply answers that every living thing deserves a chance. His story shows that you do not have to be rich or grown up to make a difference. A small idea, a lot of effort and a kind heart can be enough to change the world a little.', 'Volunteering', 158, '[{"q":"How did Joris get the money he needed?","answer":"A","options":["By selling things and holding events to raise funds.","By asking the government for a large gift.","By winning a school competition.","By borrowing it from a wildlife club."],"explanation":"原文卖柠檬水、花、T恤并组织活动筹钱的转述;其余选项原文未提或相反。"},{"q":"What were the GPS collars used for?","answer":"B","options":["To decorate the cheetahs.","To track and protect the cheetahs.","To sell to other countries.","To keep the cheetahs in a zoo."],"explanation":"原文 ''track and protect the animals'' 的转述。"},{"q":"What main lesson does Joris''s story teach?","answer":"A","options":["Even a child can make a difference.","Only adults can protect wild animals.","Helping animals is a waste of money.","Cheetahs are too far away to help."],"explanation":"末段 ''you do not have to be rich or grown up to make a difference'' 的概括转述。"}]'::jsonb, '[{"word":"cheetah","cn":"猎豹"},{"word":"extinction","cn":"灭绝"},{"word":"collar","cn":"颈圈"},{"word":"conservation","cn":"保护"}]'::jsonb, 2, 'elective1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Website Built by Twins', 'Jake and Max are twin brothers who are only fourteen years old. One day they wanted to serve meals at a shelter, but they were told that they were simply too young to help. Many children feel the same way: they want to do good, yet they do not know where to start. Instead of giving up, the twins decided to solve the problem for everyone. They launched a website and built a database that connects young people with volunteer opportunities near them. The site now receives an average of one hundred visitors every day. A growing number of groups, such as animal shelters and urban farming groups, have requested to be listed on it. Because of the twins, a child who wants to help can now find the right place in just a few minutes. What began as one closed door has opened many new ones. Their story proves that turning a personal problem into a shared solution is itself a powerful form of volunteering.', 'Volunteering', 166, '[{"q":"Why did the twins first feel disappointed?","answer":"B","options":["They had no money for the project.","They were told they were too young to help.","Their parents stopped them.","The shelter had already closed."],"explanation":"原文他们想送餐却被告知太小的转述。"},{"q":"What does the website mainly do?","answer":"C","options":["It sells food to shelters.","It teaches children how to cook.","It connects young people with places to volunteer.","It collects money for animals."],"explanation":"原文网站把年轻人与志愿机会连接起来的转述。"},{"q":"What does the writer think the twins'' story shows?","answer":"D","options":["Children should not try to volunteer.","Only big organisations can help others.","Websites are better than serving meals.","That solving a shared need is itself real volunteering."],"explanation":"末句概括其转述,其余与原文观点不符。"}]'::jsonb, '[{"word":"database","cn":"数据库"},{"word":"shelter","cn":"收容所"},{"word":"urban","cn":"城市的"},{"word":"list","cn":"列入名单"}]'::jsonb, 2, 'elective1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Fighting Plastic Pollution', 'Jackson is seventeen, and he has always cared about the problem of plastic pollution. He serves as the president of an environmental club at his school. This year, he organised a march in his county to raise awareness of water rights, and many people walked with him to show their support. But Jackson believes that one march is not enough. He is also leading a campaign in his town to promote the use of reusable water bottles. His team is urging local restaurants to join the movement by selling more paper cups and bottles instead of plastic ones. "Change does not happen overnight," Jackson says, "but every bottle we save still matters." Some people argue that one teenager cannot change the habits of a whole town. Jackson disagrees. He thinks that big movements always start with small actions taken by ordinary people. Step by step, his town is beginning to throw away less plastic, and other schools nearby have started similar clubs of their own.', 'Volunteering', 165, '[{"q":"What did Jackson organise in his county this year?","answer":"A","options":["A protest march about water rights.","A sports competition.","A school exam.","A music festival."],"explanation":"原文他在县里组织游行提高水权意识的转述。"},{"q":"What is Jackson''s team asking local restaurants to do?","answer":"B","options":["To close down completely.","To offer paper bottles in place of plastic ones.","To stop serving water.","To give free meals to students."],"explanation":"原文力劝餐馆多卖纸瓶代替塑料的转述。"},{"q":"What does Jackson believe about big movements?","answer":"C","options":["They can never succeed.","They need a famous leader.","They begin with small actions by ordinary people.","They should be left to the government."],"explanation":"原文 ''big movements always start with small actions'' 的转述。"}]'::jsonb, '[{"word":"campaign","cn":"运动"},{"word":"promote","cn":"推广"},{"word":"urge","cn":"力劝"},{"word":"reusable","cn":"可重复使用的"}]'::jsonb, 2, 'elective1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Guide in the Old Palace', 'Xiao Meng is a twenty-year-old student in Beijing, and she is one of around three hundred volunteer tour guides in the Forbidden City. From a distance she looks like any other visitor, walking quietly among the crowds, but she wears a red "volunteer" card on her chest. Becoming a good guide was not easy. It took her about three months to remember every detail of the one hundred and seventy-six clocks in the clock gallery of the Palace Museum. She loves spending time in the buildings where twenty-five emperors once spent their whole lives. "Every brick has a story to tell," she likes to say. For Xiao Meng, the work is not only about sharing facts with strangers. It is also a way of keeping the past alive and passing it on to a new generation. When tourists thank her with shining eyes, she feels that all those long hours of study were truly worth it.', 'Volunteering', 156, '[{"q":"How can people tell that Xiao Meng is a volunteer?","answer":"D","options":["She carries a large flag.","She wears a special hat.","She walks far from the crowds.","By the red volunteer card she has on."],"explanation":"原文她戴红色志愿者卡的转述。"},{"q":"What took Xiao Meng about three months?","answer":"A","options":["Learning every detail of the clocks in the gallery.","Travelling to Beijing.","Building the palace.","Writing a book about emperors."],"explanation":"原文她花三个月记住钟表细节的转述。"},{"q":"Why does Xiao Meng find her work meaningful?","answer":"B","options":["It earns her a high wage.","It keeps the past alive for a new generation.","It lets her travel for free.","It helps her avoid school."],"explanation":"原文她视之为让过去存续、传给新一代的转述。"}]'::jsonb, '[{"word":"gallery","cn":"陈列室"},{"word":"emperor","cn":"皇帝"},{"word":"brick","cn":"砖块"},{"word":"generation","cn":"一代人"}]'::jsonb, 2, 'elective1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Lesson from Tanzania', 'A few years ago, Pippa joined a school trip to Tanzania. Her group of students went to an orphanage, where their mission was to build a library. They were all highly educated, yet they were so bad at the basic construction work that the local men had to come back each night to rebuild it in secret. In the end, the money paid for two libraries: the poor one the students made by day, and the real one built quietly at night. Pippa felt that they had failed at the only purpose of their visit. She also brought hair bands as gifts, which seemed logical to her, until she saw that the local schoolgirls all had closely cropped hair and could not use them at all. Looking back, Pippa believes the trip taught her something important. If you truly want to help a community, she says, you should do careful research first and never assume that others value the same things you do.', 'Volunteering', 163, '[{"q":"Why did the local men rebuild the library at night?","answer":"C","options":["They wanted to make it larger.","They were paid extra to do so.","The students'' construction work was too poor.","The students asked them to."],"explanation":"原文学生建筑活儿太差、当地人夜里偷偷重建的转述。"},{"q":"Why were the hair bands a useless gift?","answer":"D","options":["They were too expensive.","The girls already had many of them.","They broke during the trip.","The local girls had very short hair."],"explanation":"原文女生头发剪得很短、用不上的转述。"},{"q":"What lesson did Pippa learn from the trip?","answer":"A","options":["Do research first and respect what others value.","Never travel to other countries.","Gifts are always a bad idea.","Only adults should volunteer abroad."],"explanation":"末段先做调查、别想当然假设的转述。"}]'::jsonb, '[{"word":"orphanage","cn":"孤儿院"},{"word":"construction","cn":"建造"},{"word":"cropped","cn":"剪短的"},{"word":"assume","cn":"想当然地认为"}]'::jsonb, 2, 'elective1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'International Volunteer Day', 'The act of volunteering is found in all cultures around the world. Every year, hundreds of millions of people give their time and skills to help make the world a better place. When they volunteer, they not only improve the lives of others but also gain a stronger sense of belonging to their own communities. To celebrate this spirit, the world marks International Volunteer Day on the fifth of December each year. On that day, people hold parades, volunteer fairs, group clean-ups, blood donations, conferences and exhibitions. Some plant trees, others read to elderly people, and many simply spend a few hours helping neighbours they have never met before. The day reminds us that volunteering is not a rare or distant thing. It is something almost anyone can do, in big ways or small. Whether you give a whole weekend or just a single afternoon, your effort joins millions of others and helps to build a kinder, more connected world for everyone.', 'Volunteering', 162, '[{"q":"What do volunteers gain besides helping others?","answer":"B","options":["A large amount of money.","A deeper feeling of belonging in their own communities.","A free holiday abroad.","A chance to avoid work."],"explanation":"原文他们也获得对社区的归属感的转述。"},{"q":"When is International Volunteer Day held?","answer":"C","options":["On the first of January.","On any weekend in spring.","Each year on December the fifth.","Once every two years."],"explanation":"原文 ''on the fifth of December'' 的对应。"},{"q":"What main idea does the passage express about volunteering?","answer":"D","options":["Only special people can volunteer.","Volunteering should last a whole month.","Volunteering is mostly about parades.","Almost anyone can volunteer in big or small ways."],"explanation":"末段几乎人人都能以大小方式参与的概括转述。"}]'::jsonb, '[{"word":"parade","cn":"游行"},{"word":"donation","cn":"捐献"},{"word":"belonging","cn":"归属感"},{"word":"community","cn":"社区"}]'::jsonb, 2, 'elective1', 'U2', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U2', 'My First Day as a Volunteer', 'Last summer I signed up to (1)____ at a small animal shelter near my home. On my first morning I felt nervous, because I did not know (2)____ I could really be useful. A kind worker showed me (3)____ to clean the cages and feed the dogs safely. At first the work was hard and a little (4)____, and my back hurt by lunchtime. But when a frightened puppy finally came close and let me (5)____ it, all my tiredness disappeared. The manager told me (6)____ even small jobs matter a lot to the animals. By the end of the day I had learned (7)____ to care for several pets. I also made a few new (8)____ among the other helpers. I now go back every (9)____, and I am proud of the difference we (10)____ together. Volunteering has quickly become the best part of my week.', 147, 2, '[{"q":"1","answer":"A","options":["volunteer","buy","sell","drive"],"explanation":"volunteer 做志愿者。"},{"q":"2","answer":"B","options":["that","whether","which","what"],"explanation":"did not know 后转述是否问题,用 whether。"},{"q":"3","answer":"C","options":["that","if","how","why"],"explanation":"showed me how to do 教我怎么做。"},{"q":"4","answer":"D","options":["funny","lovely","lucky","awkward"],"explanation":"a little awkward 有点别扭。"},{"q":"5","answer":"A","options":["touch","throw","sell","lose"],"explanation":"let me touch it 让我摸它。"},{"q":"6","answer":"B","options":["if","that","what","which"],"explanation":"told me that 后接陈述。"},{"q":"7","answer":"C","options":["that","if","how","why"],"explanation":"learned how to care 学会怎样照顾。"},{"q":"8","answer":"D","options":["prices","mistakes","machines","friends"],"explanation":"made new friends 交了新朋友。"},{"q":"9","answer":"A","options":["weekend","year","century","never"],"explanation":"every weekend 每个周末。"},{"q":"10","answer":"B","options":["lose","make","break","sell"],"explanation":"make a difference 带来改变。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U2', 'An Afternoon at the Care Home', 'Every Sunday afternoon, our class (1)____ to visit an old people''s care home in our town. Most of the residents live far from their families, so they are always (2)____ to see young faces. When we arrive, we ask them (3)____ they would like to do that day. Some want to play chess, while others simply (4)____ to talk about their past. I once asked an old man (5)____ he had spent his life, and his stories kept us listening for an hour. Helping there has taught me (6)____ a little time can mean so much to someone who is (7)____. The care home staff often say (8)____ our visits bring real joy to the place. Before we leave, the residents always (9)____ us to come again soon. I now understand (10)____ my grandmother used to enjoy company so much.', 140, 2, '[{"q":"1","answer":"C","options":["refuses","forgets","volunteers","sells"],"explanation":"volunteers to visit 自愿去探访。"},{"q":"2","answer":"D","options":["sorry","angry","afraid","happy"],"explanation":"happy to see 很高兴见到。"},{"q":"3","answer":"A","options":["what","that","if","which"],"explanation":"ask them what they would like 转述特殊疑问,用 what。"},{"q":"4","answer":"B","options":["fail","want","stop","lose"],"explanation":"want to talk 想聊天。"},{"q":"5","answer":"C","options":["that","if","how","whether"],"explanation":"asked him how he had spent 转述特殊疑问,用 how。"},{"q":"6","answer":"D","options":["if","what","which","that"],"explanation":"taught me that 后接陈述。"},{"q":"7","answer":"A","options":["lonely","rich","young","busy"],"explanation":"someone who is lonely 孤独的人。"},{"q":"8","answer":"B","options":["if","that","what","which"],"explanation":"say that 后接陈述。"},{"q":"9","answer":"C","options":["sell","break","urge","lose"],"explanation":"urge us to come again 力劝我们再来。"},{"q":"10","answer":"D","options":["that","if","whether","why"],"explanation":"understand why 转述原因,用 why。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U2', 'Cleaning Up the Beach', 'One Saturday our environmental club held a beach (1)____ to fight against plastic pollution. More than fifty students came, each carrying a bag to (2)____ rubbish. We did not (3)____ how much waste we would find, but the beach turned out to be covered in plastic bottles and bags. Our leader explained (4)____ even one small bottle can harm sea animals for years. So we worked hard all morning to (5)____ the sand clean again. By noon we had filled dozens of (6)____ with plastic waste. A passing fisherman thanked us and asked (7)____ we did this kind of work. We told him (8)____ we wanted to protect the ocean for the future. The day was tiring, but it felt (9)____. As we walked home, we (10)____ each other to keep the beach clean in the months ahead.', 138, 2, '[{"q":"1","answer":"A","options":["clean-up","party","race","market"],"explanation":"a beach clean-up 海滩清洁活动。"},{"q":"2","answer":"B","options":["eat","collect","sell","hide"],"explanation":"collect rubbish 收集垃圾。"},{"q":"3","answer":"C","options":["that","what","know","which"],"explanation":"did not know 不知道。"},{"q":"4","answer":"D","options":["if","what","which","that"],"explanation":"explained that 后接陈述。"},{"q":"5","answer":"A","options":["make","leave","lose","throw"],"explanation":"make the sand clean 使沙滩变干净。"},{"q":"6","answer":"B","options":["prices","bags","songs","games"],"explanation":"filled dozens of bags 装满几十个袋子。"},{"q":"7","answer":"C","options":["that","whether","why","if"],"explanation":"asked why 转述原因,用 why。"},{"q":"8","answer":"D","options":["if","what","which","that"],"explanation":"told him that 后接陈述。"},{"q":"9","answer":"A","options":["rewarding","boring","useless","wrong"],"explanation":"felt rewarding 感到有意义。"},{"q":"10","answer":"B","options":["sold","urged","lost","broke"],"explanation":"urged each other 互相敦促。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U2', 'Teaching Children to Read', 'After school I (1)____ at a free reading class for younger children whose parents work late. At first I was not sure (2)____ I could teach anyone, since I am only a student myself. But my teacher said (3)____ patience matters more than perfect skill. Each afternoon I help a child choose a book and read it slowly, asking (4)____ they understand every page. When a shy boy finally read a whole story by (5)____, his happy smile made all my effort worth it. The children often ask me (6)____ words mean, and answering them makes me feel useful. Their parents have told me (7)____ grateful they are for the help. I have learned (8)____ teaching others also teaches me a lot. Now I look (9)____ to these afternoons every week. Helping these children (10)____ a real difference in their school marks.', 142, 2, '[{"q":"1","answer":"C","options":["refuse","sleep","volunteer","sell"],"explanation":"volunteer at a class 在班里做志愿者。"},{"q":"2","answer":"D","options":["that","what","which","whether"],"explanation":"not sure whether 不确定是否,用 whether。"},{"q":"3","answer":"A","options":["that","if","what","which"],"explanation":"said that 后接陈述。"},{"q":"4","answer":"B","options":["that","if","why","which"],"explanation":"asking if they understand 转述是否,用 if。"},{"q":"5","answer":"C","options":["price","noise","himself","machine"],"explanation":"read by himself 自己读。"},{"q":"6","answer":"D","options":["that","if","whether","what"],"explanation":"ask me what words mean 转述特殊疑问,用 what。"},{"q":"7","answer":"A","options":["how","that","if","which"],"explanation":"told me how grateful they are 转述感叹,用 how。"},{"q":"8","answer":"B","options":["if","that","what","which"],"explanation":"learned that 后接陈述。"},{"q":"9","answer":"C","options":["after","down","forward","into"],"explanation":"look forward to 盼望。"},{"q":"10","answer":"D","options":["loses","breaks","sells","makes"],"explanation":"makes a real difference 带来真正的改变。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U2', 'Helping at the Food Bank', 'On weekends I help out at a local food (1)____ that gives meals to families in need. My job is to sort the donations and (2)____ them into boxes for delivery. People from all over the city (3)____ rice, oil and other food, and we make sure nothing is (4)____. The manager once asked me (5)____ I had ever felt hungry myself, and his question made me think deeply. He told me (6)____ many of the families were once just like mine. I now understand (7)____ such places are so important in a big city. Every box we pack can feed a family for a (8)____. The work can be hard, but the smiles we (9)____ in return are worth it. I no longer (10)____ for granted the food on my own table at home.', 135, 2, '[{"q":"1","answer":"A","options":["bank","garden","market","stadium"],"explanation":"a food bank 食物银行。"},{"q":"2","answer":"B","options":["eat","pack","sell","lose"],"explanation":"pack them into boxes 装进箱子。"},{"q":"3","answer":"C","options":["buy","throw","donate","hide"],"explanation":"donate food 捐赠食物。"},{"q":"4","answer":"D","options":["safe","ready","clean","wasted"],"explanation":"nothing is wasted 没有浪费。"},{"q":"5","answer":"A","options":["whether","that","what","which"],"explanation":"asked me whether 转述是否,用 whether。"},{"q":"6","answer":"B","options":["if","that","what","which"],"explanation":"told me that 后接陈述。"},{"q":"7","answer":"C","options":["that","if","why","whether"],"explanation":"understand why 转述原因,用 why。"},{"q":"8","answer":"D","options":["second","metre","price","week"],"explanation":"for a week 维持一周。"},{"q":"9","answer":"A","options":["get","lose","break","sell"],"explanation":"the smiles we get 我们收获的笑容。"},{"q":"10","answer":"B","options":["give","take","sell","throw"],"explanation":"take ... for granted 把……视为理所当然。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U2', 'Why Volunteering Matters', 'Some people probably (1)____ that volunteer work is just hard work with no pay, but in fact it can change your life in surprising ways. While volunteering, you can find out (2)____ kind of work suits you and build a clearer goal for the future. It is also a great way to learn (3)____ you are good at working in a team. When you help others, you often discover skills you did not (4)____ know you had. Volunteering can raise your (5)____ by giving you the chance to try something new. It also helps you to (6)____ what you already have instead of worrying about small things. Many volunteers say (7)____ they receive far more than they give. The most important thing is to choose work that (8)____ something to you. If the work feels like a (9)____, it will not bring you much joy. In the end, helping others is also a way of (10)____ yourself.', 157, 2, '[{"q":"1","answer":"C","options":["sell","throw","assume","hide"],"explanation":"assume that 想当然认为。"},{"q":"2","answer":"D","options":["that","if","whether","what"],"explanation":"find out what kind 转述,用 what。"},{"q":"3","answer":"A","options":["whether","that","why","which"],"explanation":"learn whether 转述是否,用 whether。"},{"q":"4","answer":"B","options":["never","even","soon","ever"],"explanation":"did not even know 甚至不知道。"},{"q":"5","answer":"C","options":["price","noise","confidence","weather"],"explanation":"raise your confidence 提升自信。"},{"q":"6","answer":"D","options":["waste","sell","lose","value"],"explanation":"value what you have 珍惜所拥有的。"},{"q":"7","answer":"A","options":["that","if","what","which"],"explanation":"say that 后接陈述。"},{"q":"8","answer":"B","options":["sells","means","breaks","loses"],"explanation":"means something to you 对你有意义。"},{"q":"9","answer":"C","options":["gift","song","chore","game"],"explanation":"feels like a chore 像苦差事。"},{"q":"10","answer":"D","options":["selling","hiding","losing","helping"],"explanation":"a way of helping yourself 也是帮助自己。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 A Volunteer Interview', '上外版选择性必修第一册 U2 · dialogue', 3, 'Interviewer: Welcome, Xu Yuan. May I ask why you want to volunteer with us?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 Benefits of Volunteering', '上外版选择性必修第一册 U2 · passage', 2, 'Volunteering brings many benefits to the people who do it.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Choosing Volunteer Work', '上外版选择性必修第一册 U2 · dialogue', 3, 'Lily: I want to start volunteering, but I''m not sure where to begin.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 A Call for Volunteers', '上外版选择性必修第一册 U2 · passage', 2, 'Our summer camp is looking for volunteers, and we need you.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Visiting the Care Home', '上外版选择性必修第一册 U2 · dialogue', 3, 'Anna: How was your visit to the care home today?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 International Volunteer Day', '上外版选择性必修第一册 U2 · passage', 2, 'Every year, the world celebrates International Volunteer Day on the fifth of December.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write an essay for a column "Voices of Volunteers"(为专栏写一篇志愿服务短文)', 'Helping Others Helps You', '假设你是学校公众号 ''Voices of Volunteers'' 专栏的撰稿人,为庆祝国际志愿者日写一篇约90-110词的短文,内容包括:① 先给出一个关于志愿服务的总论点;② 引用一两句他人的话(quote)来支撑你的论点,并简要解释这句话;③ 用一句话总结收尾。注意:用宾语从句(He said that … / I believe that …)来引述,行文连贯。', 'Suppose you write for your school''s online column "Voices of Volunteers." To celebrate International Volunteer Day, write a short essay (about 90-110 words) including: 1) a general statement about volunteering; 2) one or two quotes from others to support your statement, with a short explanation; 3) a concluding sentence. Use object clauses (He said that … / I believe that …) to report what people say.', '["给出总论点(I believe that volunteering … / Volunteering is …)","引用并解释引语(As Ben said, \"…\" This shows that …)","用宾语从句引述他人的话(He said that … / She believes that …)","一句话总结收尾(In short, … / The happiest people are those who give.)"]'::jsonb, 70, 100, 'Helping others helps you too. I believe that volunteering not only improves your community but also makes your own life richer. Ben, a college student who did volunteer work, said that it was a win-win situation. He explained that helpers feel good because they are giving, and others feel good because they are getting help. This shows that kindness flows in two directions at once. As an old saying goes, "The fragrance of the rose lingers on the hand that casts it." In short, the happiest people are those who give, and give generously, to the world around them.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I believe that volunteering not only improves your community but also makes your own life richer.","Ben said that it was a win-win situation.","He explained that helpers feel good because they are giving, and others feel good because they are getting help.","The happiest people are those who give, and give generously."]'::jsonb, '[{"wrong":"He said it is a win-win situation.","correct":"He said that it was a win-win situation.","note":"主句过去时(said),宾语从句一般也用过去时(was)。"},{"wrong":"I believe volunteering improves your community and also makes richer your life.","correct":"I believe that volunteering improves your community and also makes your life richer.","note":"make + 宾语 + 形容词,形容词放宾语后:makes your life richer。"},{"wrong":"She explained why she volunteers it helps others.","correct":"She explained that she volunteers because it helps others.","note":"引述陈述内容用 that 引导宾语从句,不要漏掉连接词。"}]'::jsonb, '【志愿服务专栏短文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U2', '{"title":"宾语从句(复习)速查","intro":"宾语从句 = 主语 + 动词 + 一个充当宾语的从句。三步走:① 选对连接词;② 从句一律用陈述语序(主语在前);③ 主句过去时,从句一般也用相应的过去时。口诀:陈述用 that,是否用 if/whether,带疑问词就照搬疑问词。","table":{"headers":["从句原本是","用什么连接词","例句"],"rows":[["陈述句","that(常可省略)","I believe (that) volunteering helps you."],["一般疑问句(Yes/No)","if / whether","She asked if I had any experience."],["特殊疑问句(wh-)","what/who/where/when/why/how","He told me where she would work."],["疑问词作主语","who/what(语序不变)","Tell me who started the website."]]},"specialRules":[{"rule":"从句一律陈述语序:疑问词/if + 主语 + 谓语,不再倒装","mark":"what my strength was √ / what was my strength ×"},{"rule":"主句过去时,从句一般用相应的过去时(过去/过去完成/过去将来)","mark":"She asked where I would work."},{"rule":"ask/wonder/want to know + 是否类内容 → if/whether,不用 that","mark":"wonder whether √ / wonder that ×"},{"rule":"介词后、句首、与 or not 连用时只能用 whether,不用 if","mark":"whether or not √ / if or not ×"}],"why":["宾语从句是把一句话''装进''另一句话当宾语:原句一旦成了从句,就不再是独立的问句,所以要去掉疑问语序、改回主语在前的陈述语序;连接词只负责''连接''和''表明原句类型''(陈述/是否/特殊疑问)。"],"gaokaoPoints":["语序题高频:疑问句变宾语从句必须改陈述语序(不倒装、不加 do/does/did)。","连接词选择:陈述 that、是否 if/whether、特殊疑问照搬 wh-;时态呼应(主过去→从过去)。"],"examVsReal":[{"exam":"He asked me whether I had finished.(考试/书面)","real":"He asked, \"Have you finished?\"","note":"考试爱考转述(陈述语序);口语里常直接引用原话。"},{"exam":"I think that he is right.(考试常带 that)","real":"I think he''s right.","note":"口语里 that 几乎总被省略,但考试写出来更稳妥。"}]}'::jsonb, 'sufe');
